// Helper functions
export function getProductBySlug(slug: string): Product | undefined {
  return products.find((p) => p.slug === slug)
}

export function getProductById(id: string): Product | undefined {
  return products.find((p) => p.id === id)
}

export function getProductsByCategory(category: ProductCategory): Product[] {
  return products.filter((p) => p.category === category)
}

export function getRelatedProducts(product: Product, limit = 3): Product[] {
  return products
    .filter((p) => p.category === product.category && p.id !== product.id)
    .slice(0, limit)
}

export function getAllBrands(): string[] {
  return [...new Set(products.map((p) => p.brand))]
}

export function getAllSizes(): string[] {
  const sizes = products.map((p) => p.size).filter((s) => s && s !== '—')
  return [...new Set(sizes)]
}

export function getAllTopSheets(): string[] {
  const sheets = products.map((p) => p.topSheet).filter((s) => s && s !== '—')
  return [...new Set(sheets)]
}

export const productStats = {
  total: products.length,
  napkins: products.filter((p) => p.category === 'sanitary-napkins').length,
  pads: products.filter((p) => p.category === 'sanitary-pad').length,
  brands: getAllBrands().length,
  withBIS: products.filter((p) => p.certifications.includes('BIS')).length,
}
